#!/usr/bin/env bash

# fix segmentation fault reported in https://github.com/k2-fsa/icefall/issues/674
export PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python

set -eou pipefail

nj=15
stage=0
stop_stage=100

. shared/parse_options.sh || exit 1

# All files generated by this script are saved in "data".
# You can safely remove "data" and rerun this script to regenerate it.
mkdir -p data

log() {
  # This function is from espnet
  local fname=${BASH_SOURCE[1]##*/}
  echo -e "$(date '+%Y-%m-%d %H:%M:%S') (${fname}:${BASH_LINENO[0]}:${FUNCNAME[1]}) $*"
}

if [ $stage -le 0 ] && [ $stop_stage -ge 0 ]; then
  log "Stage 0: Prepare WenetSpeech (Chinese) dataset."
  mkdir -p data/fbank
  if [ ! -e data/fbank/.wenetspeech.done ]; then
    pushd ../wenetspeech/ASR
    ./prepare.sh --stage 0 --stop-stage 17
    popd
    wenetspeech_fbank=$(realpath ../wenetspeech/ASR/data/fbank)
    pushd data/fbank
    for f in cuts_DEV.jsonl.gz feats_DEV.lca \
             cuts_TEST_NET.jsonl.gz feats_TEST_NET.lca \
             cuts_TEST_MEETING.jsonl.gz feats_TEST_MEETING.lca \
             cuts_L.jsonl.gz L_split_1000 \
             musan_cuts.jsonl.gz musan_feats; do
      ln -svf $wenetspeech_fbank/$f .
    done
    popd
    touch data/fbank/.wenetspeech.done
  else
    log "WenetSpeech dataset already exists, skipping."
  fi
fi

if [ $stage -le 1 ] && [ $stop_stage -ge 1 ]; then
  log "Stage 1: Prepare GigaSpeech (English) dataset."
  mkdir -p data/fbank
  if [ ! -e data/fbank/.gigaspeech.done ]; then
    pushd ../gigaspeech/ASR
    ./prepare.sh --stage 0 --stop-stage 9
    ./prepare.sh --stage 11 --stop-stage 11
    popd
    gigaspeech_fbank=$(realpath ../gigaspeech/ASR/data/fbank)
    pushd data/fbank
    for f in gigaspeech_cuts_DEV.jsonl.gz gigaspeech_cuts_TEST.jsonl.gz \
             gigaspeech_XL_split; do
      ln -svf $gigaspeech_fbank/$f .
    done
    popd
    touch data/fbank/.gigaspeech.done
  else
    log "GigaSpeech dataset already exists, skipping."
  fi
fi

if [ $stage -le 2 ] && [ $stop_stage -ge 2 ]; then
  log "Stage 2: Prepare bilingual phone lang (cppinyin g2p)."
  if ! python3 -c "import cppinyin" 2>/dev/null; then
    pip install cppinyin==0.11
  fi
  python3 local/prepare_lang_phone.py --lang-dir data/lang_phone
fi
